	private static Stream<Direction> directions() {
		return Stream.of(new Direction(TripleIndex.SUBJ_IDX, "s", 0),
				new Direction(TripleIndex.OBJ_IDX, "o", 1));
	}

	private static List<String> bindings(List<BindingSet> rows, String groupName) {
		List<String> result = new ArrayList<>(rows.size());
		for (BindingSet row : rows) {
			result.add(row.getValue(groupName) + "=" + row.getValue("count"));
		}
		return result;
	}

	private static List<String> expectedBindings(Direction direction) {
		List<String> result = new ArrayList<>(GROUPS);
		for (int index = 0; index < GROUPS; index++) {
			result.add(groupValue(direction, index) + "=\"2\"^^<http://www.w3.org/2001/XMLSchema#integer>");
		}
		return result;
	}

	private static Literal groupValue(Direction direction, int index) {
		long id = 10_000L + direction.rootField * 1_000L + index;
		return SimpleValueFactory.getInstance().createLiteral("group-" + id + "-" + "🧭λ".repeat(180));
	}

	private static Set<String> resultSpills() throws IOException {
		try (Stream<Path> paths = Files.list(Path.of(System.getProperty("java.io.tmpdir")))) {
			return paths.map(path -> path.getFileName().toString())
					.filter(name -> name.startsWith("rdf4j-lmdb-result-") && name.endsWith(".spill"))
					.collect(java.util.stream.Collectors.toCollection(TreeSet::new));
		}
	}

	private static Set<String> difference(Set<String> current, Set<String> original) {
		Set<String> added = new TreeSet<>(current);
		added.removeAll(original);
		return added;
	}

	private static void restore(String key, String value) {
		if (value == null) {
			System.clearProperty(key);
		} else {
			System.setProperty(key, value);
		}
	}

