	private static final class Fixture implements AutoCloseable {
		final SyntheticValueSource source;
		final NativeSlotLayout layout;
		final PatternPlan pattern;
		final AggregateSpec[] aggregates = { AggregateSpec.star("count") };
		final LmdbAdjacencyAggregatePlan plan;
		final NativeGroupIteration owner;
		final LmdbQueryMemoryManager.QueryLedger ledger;
		final AtomicInteger cursorOpens = new AtomicInteger();
		final AtomicInteger cursorAdvances = new AtomicInteger();
		final AtomicInteger cursorCloses = new AtomicInteger();
		final AtomicLong peakLedgerBytes = new AtomicLong();
		final IOException scanFailure = new IOException("injected adjacency prefix failure");
		final Direction direction;

		Fixture(Direction direction, int failAt) throws Exception {
			this.direction = direction;
			NativeLmdbQuerySource delegate = mock(NativeLmdbQuerySource.class, CALLS_REAL_METHODS);
			when(delegate.idSpace()).thenReturn(delegate);
			when(delegate.hasCanonicalIds()).thenReturn(true);
			when(delegate.idOf(any(Value.class))).thenReturn(NativeLmdbQuerySource.UNKNOWN_ID);
			when(delegate.idOf(any(Value.class), anyInt())).thenReturn(NativeLmdbQuerySource.UNKNOWN_ID);
			when(delegate.lazyValue(anyLong(), anyInt())).thenAnswer(call -> {
				long id = call.getArgument(0);
				int index = Math.toIntExact(id - 10_000L - direction.rootField * 1_000L);
				return groupValue(direction, index);
			});
			LmdbPrefixRunPlan prefixPlan = mock(LmdbPrefixRunPlan.class);
			when(prefixPlan.usesAdjacency()).thenReturn(true);
			when(prefixPlan.prefixFields()).thenReturn(new int[] { direction.rootField });
			when(delegate.prefixRunPlan(any(int[].class), anyLong(), anyLong(), anyLong(), anyLong()))
					.thenReturn(prefixPlan);
			when(delegate.prefixRuns(any(LmdbPrefixRunPlan.class), anyLong(), anyLong(), anyLong(), anyLong(),
					anyBoolean(), nullable(NativeLmdbQuerySource.AdjacencyAccessObserver.class)))
							.thenAnswer(call -> openCursor(failAt));
			source = SyntheticValueSource.forEvaluation(delegate);
			ledger = source.executionContext().memoryLedger();
			layout = new NativeSlotLayout(Map.of("s", 0, "o", 1), null);
			layout.freeze(List.of("s", "o"));
			pattern = new PatternPlan(Term.slot(0), Term.constant(PREDICATE), Term.slot(1), Term.unbound(),
					ContextConstraint.UNRESTRICTED, false, GROUPS * ROWS_PER_GROUP);
			plan = LmdbAdjacencyAggregatePlan.tryCreate(pattern, new int[] { direction.groupSlot }, aggregates);
			assertNotNull(plan, "the direct grouped fixture must be a real adjacency aggregate plan");
			owner = new NativeGroupIteration(source, pattern, layout, new int[] { direction.groupSlot }, aggregates,
					false, EmptyBindingSet.getInstance(), null, null, false, false, null, null, 0L, null, plan, null,
					null,
					LmdbNativeAttemptMetrics.PATH_ADJACENCY_AGGREGATE);
		}

		private LmdbPrefixRunCursor openCursor(int failAt) throws IOException {
			cursorOpens.incrementAndGet();
			LmdbPrefixRunCursor cursor = mock(LmdbPrefixRunCursor.class);
			org.mockito.Mockito.doAnswer(call -> {
				int position = cursorAdvances.getAndIncrement();
				if (position == failAt) {
					throw scanFailure;
				}
				if (position >= GROUPS) {
					peakLedgerBytes.accumulateAndGet(ledger.usedBytes(), Math::max);
					return false;
				}
				peakLedgerBytes.accumulateAndGet(ledger.usedBytes(), Math::max);
				return true;
			}).when(cursor).next();
			when(cursor.prefixValue(anyInt())).thenAnswer(call -> {
				int field = call.getArgument(0);
				if (field != direction.rootField) {
					throw new AssertionError("prefix cursor requested a different root field: " + field);
				}
				return 10_000L + direction.rootField * 1_000L + cursorAdvances.get() - 1L;
			});
			when(cursor.runRowCount()).thenReturn(ROWS_PER_GROUP);
			org.mockito.Mockito.doAnswer(call -> {
				cursorCloses.incrementAndGet();
				return null;
			}).when(cursor).close();
			return cursor;
		}

		@Override
		public void close() {
			try {
				owner.close();
			} finally {
				source.executionContext().close();
			}
		}
	}

